package com.suresh.lifeos;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;import java.util.*;
public class OverdueReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){Store s=Store.get(c);long id=i.getLongExtra("task_id",-1);String day=i.getStringExtra("day");String title=i.getStringExtra("title");int stage=i.getIntExtra("stage",0);int penalty=i.getIntExtra("penalty",100);int points=i.getIntExtra("points",5);if(id<0||day==null||s.hasTaskLog(id,day))return;
  if(stage>=4){s.logTaskForDay(id,day,"AUTO_MISSED","Not marked within the 60-minute grace period",Math.max(1,points));addMoneyPenalty(s,c,day,"Auto-missed: "+title,penalty);notify(c,(int)(id*1000+stage),"Task automatically marked missed","The grace hour ended. Open Life OS to review it.",id);}
  else{String msg=stage==1?"15 minutes overdue — still not marked.":stage==2?"30 minutes overdue — please complete or mark it.":"45 minutes overdue — 15 minutes remain before auto-miss.";notify(c,(int)(id*1000+stage),"Private task still pending",msg,id);}
 }
 static void addMoneyPenalty(Store s,Context c,String day,String why,int amount){int dc=parse(s.get("daily_penalty_cap","500"),500),wc=parse(s.get("weekly_penalty_cap","2000"),2000);int today=0,week=0;for(Map<String,String>m:s.q("SELECT amount FROM penalties WHERE day=?",day))today+=parse(m.get("amount"),0);LocalDate d=LocalDate.parse(day);LocalDate st=d.with(DayOfWeek.MONDAY);for(Map<String,String>m:s.q("SELECT amount FROM penalties WHERE day>=? AND day<=?",st.toString(),day))week+=parse(m.get("amount"),0);amount=Math.max(0,Math.min(amount,Math.min(dc-today,wc-week)));if(amount<=0)return;ContentValues v=new ContentValues();v.put("day",day);v.put("reason",why);v.put("amount",amount);s.insert("penalties",v);}
 static void notify(Context c,int code,String title,String text,long taskId){Intent open=new Intent(c,V15Activity.class).putExtra("task_id",taskId).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,code,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,LifeApp.CH):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Suresh Life OS").setContentText(title+" — "+text).setVisibility(Notification.VISIBILITY_SECRET).setCategory(Notification.CATEGORY_REMINDER).setPriority(Notification.PRIORITY_HIGH).setAutoCancel(true).setContentIntent(pi);c.getSystemService(NotificationManager.class).notify(code,b.build());}
 static int parse(String x,int d){try{return Integer.parseInt(x);}catch(Exception e){return d;}}
 public static void scheduleUpcoming(Context c){Store s=Store.get(c);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long now=System.currentTimeMillis();for(int off=0;off<14;off++){LocalDate day=LocalDate.now().plusDays(off);int dow=day.getDayOfWeek().getValue();for(Map<String,String>x:s.q("SELECT * FROM tasks WHERE active=1")){String days=x.get("days");if(days==null||!Arrays.asList(days.split(",")).contains(String.valueOf(dow)))continue;try{long id=Long.parseLong(x.get("id"));int start=Integer.parseInt(x.get("start_min")),dur=Integer.parseInt(x.get("duration"));int pen=parse(x.get("penalty"),100),pts=parse(x.get("points"),5);ZonedDateTime due=day.atTime(start/60,start%60).plusMinutes(Math.max(0,dur)).atZone(ZoneId.systemDefault());for(int stage=1;stage<=4;stage++){long when=due.plusMinutes(stage*15L).toInstant().toEpochMilli();if(when<=now)continue;int req=(int)((id*1237L+day.toEpochDay()*7+stage)&0x7fffffff);Intent i=new Intent(c,OverdueReceiver.class).putExtra("task_id",id).putExtra("day",day.toString()).putExtra("title",x.get("title")).putExtra("stage",stage).putExtra("penalty",pen).putExtra("points",pts);PendingIntent p=PendingIntent.getBroadcast(c,req,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms())a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}}catch(Exception ignored){}}}}
}
